const token = Symbol('Email');
export class Email {
  constructor(value, t) {
    if (t !== token) throw new TypeError('use Email.from');
    this.value = value;
  }
  static from(text) {
    const value = text.trim().toLowerCase();
    if (!value.includes('@')) throw new RangeError('invalid address');
    return new Email(value, token);
  }
}
